drop table if exists shopitems;

create table shopitems(
	id bigint not null auto_increment,
    shopid int,
    itemid int,
    price bigint default 0,
    tokenitemid int default 0,
    tokenprice int default 0,
    pointquestid int default 0,
    pointprice int default 0,
    starcoin int default 0,
    questexid int default 0,
    questexkey varchar(255),
    questexvalue int default 0,
    itemperiod int default 0,
    levellimited int default 0,
    showlevmin int default 0,
    showlevmax int default 0,
    questid int default 0,
    sellstart datetime(3) default '1970-01-01 00:00:01.000',
    sellend datetime(3) default '9999-01-01 00:00:01.000',
    tabindex int,
    worldblock boolean,
    potentialgrade int,
    buylimit int,
    quantity smallint,
    unitprice bigint default 0,
    maxperslot smallint default 9999,
    discountperc int default 0,
    primary key (id)
);

drop table if exists itemsbuylimit;
create table itemsbuylimit (
  id int not null auto_increment,
  shopitemid bigint,
  charid int,
  amountbought int ,
  primary key(id),
  foreign key (charid) references characters(id),
  foreign key (shopitemid) references shopitems(id)
) engine=MyISAM;

